"""Build a fully offline, source-linked research view from saved result tables."""
from pathlib import Path
import json
import pandas as pd

ROOT=Path(__file__).resolve().parent
OUT=ROOT/'workbench';OUT.mkdir(exist_ok=True)
def rows(path,query=None,cols=None):
 d=pd.read_csv(ROOT/path)
 if query is not None:d=query(d)
 if cols is not None:d=d[cols]
 return json.loads(d.to_json(orient='records',force_ascii=False,double_precision=12))
alliance=rows('mixtures/DSTRUCT_ALLIANCE_STRATA.csv',lambda d:d[d.axis.isin(['ALL','official_difficulty','structural_condition','purpose'])])
fixed=rows('mixtures/FIXED_N_FOCUSED_STRATA.csv',lambda d:d[(d.support=='all_teams_Q_valid_in_both_configurations') & d.axis.isin(['ALL','official_difficulty','structural_condition','purpose'])])
curve=rows('curves/LANDMARK_CURVE_SUMMARY.csv',lambda d:d[(d.anchor==6)&(d.min_arm_paths==16)])
for r in curve:r['difficulty']='ALL'
curve+=rows('curves/LANDMARK_CURVE_DIFFICULTY_SUMMARY.csv',lambda d:d[(d.anchor==6)&(d.min_arm_paths==16)])
complete=rows('curves/LANDMARK_COMPLETE_PATH_CURVE_SUMMARY.csv')
for r in complete:r['difficulty']='ALL'
curve+=complete
abc=rows('c13_half/analysis/SUMMARY.csv',lambda d:d[d.metric.isin(['Q_GS','Q_GA','Q_class_shift','Q_W','Q_cross','Q_CA','Q_CB','fusion_turn_n_CA_ABC','fusion_short_turn_edges_CA_ABC','omission_CA_ABC'])])
ledger=rows('CONCLUSION_LEDGER.csv') if (ROOT/'CONCLUSION_LEDGER.csv').exists() else []
DATA={'alliance':alliance,'fixed':fixed,'curve':curve,'abc':abc,'ledger':ledger}
figs=''.join('<figure><a href="../mixtures/'+p.name+'"><img src="../mixtures/'+p.name+'" alt="既有混合团队的配比、背景或几何证据" loading="lazy"></a></figure>' for p in sorted((ROOT/'mixtures').glob('FIG*.png')))
html=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HOHONET v2.1 · 混合人群规律与 C1↔C3</title><style>
:root{--ink:#18313e;--muted:#5c7180;--teal:#136e7d;--gold:#ab5d2c;--line:#d7e2e7;--bg:#f2f6f8}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--bg);font:16px/1.7 system-ui,"Microsoft YaHei",sans-serif}header{background:#123644;color:#fff;padding:40px max(22px,calc((100vw - 1260px)/2)) 32px}header p{color:#d7e6ec;max-width:1050px}h1{font-size:34px;line-height:1.35;margin:10px 0 18px}.eyebrow{font-size:13px;letter-spacing:.08em;color:#acdae4}nav{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}nav a{color:white;background:#235566;border:1px solid #4e7d8d;border-radius:6px;padding:7px 13px;text-decoration:none}main{max-width:1300px;margin:22px auto 50px;padding:0 20px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card,section{background:white;border:1px solid var(--line);border-radius:10px;padding:24px;margin-bottom:22px}.card{border-top:4px solid var(--teal);font-size:15px}.value{font-size:30px;font-weight:700;color:var(--teal)}h2{font-size:25px;margin:0 0 16px}h3{font-size:19px;margin-top:26px}p{margin:12px 0}.muted,figcaption{font-size:14px;color:var(--muted)}.controls{display:flex;gap:16px;flex-wrap:wrap;padding:14px;background:#edf4f6;margin:20px 0}.controls label{display:flex;flex-direction:column;font-size:13px;font-weight:600;gap:4px}select{font:15px system-ui;padding:8px;border:1px solid #a9bec8;border-radius:4px;background:#fff;max-width:350px}a{color:#0b6476;text-underline-offset:3px}.tablewrap{overflow:auto;margin:16px 0}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:10px 12px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}th{background:#eff5f6;position:sticky;top:0}td:first-child{font-weight:500}.plus{color:#0f6570}.minus{color:#9b482d}.small{font-size:12px}.chart{width:100%;min-height:280px}img{width:100%;height:auto}figure{margin:22px 0}.summary{border-left:4px solid var(--teal);padding:12px 18px;background:#f1f8f8}.sources{font-size:14px}#ledger td{white-space:normal;min-width:130px}#ledger td:last-child{min-width:400px}code{overflow-wrap:anywhere;font-size:13px}footer{font-size:14px;color:var(--muted);padding:20px}details{margin:18px 0}summary{cursor:pointer;font-weight:600}@media(max-width:850px){.cards{grid-template-columns:1fr}header{padding:28px 20px}h1{font-size:27px}section{padding:20px 15px}main{padding:0 10px}.controls{gap:10px}select{max-width:280px}}
</style></head><body><header><div class="eyebrow">HOHONET v2.1 · 第 11—12 批 · 2026-11-04</div><h1>不同类型混合后，什么变好，什么被稀释？</h1><p>完整联盟、固定人数配比、具体成员、共同背景与进入过程在同一条证据链中解释。当前 C1↔C3 的 50% 严格 ABC 已补齐；多数方向一致的规律与少数反向图片一起保留。</p><nav><a href="../REPORT_ZH.html">完整报告</a><a href="#alliance">联盟与场景</a><a href="#fixed">比例与成员</a><a href="#curve">接近参考的过程</a><a href="#abc">C1↔C3 半队</a><a href="../../current_class_interpretation_20261104/examples/index.html#method=OPPJOINT_K4">K4 原图图册</a></nav></header><main>
<div class="cards"><div class="card"><div class="value">+2.768 Q</div><strong>C2 加入 C3 后的完整联盟</strong><p>204 张共同图中 166 张提高；同一混合队相对纯 C3 又可能下降。</p></div><div class="card"><div class="value">+1.780 Q</div><strong>早期 C2+C3 对 C1+C2</strong><p>190 图中 165 图提高。比较前 6 人构成，观察已有 6—20 人路径。</p></div><div class="card"><div class="value">+7.865 Q</div><strong>同背景 C3 团队对 C1 团队</strong><p>新 6/3 双向严格 ABC，36 图/10 楼；32 图同向，四端点共同支持。</p></div></div>
<section id="alliance"><h2>1. 同一个混合队，相对不同基线会得到不同答案</h2><p>C3 加入 C1/C2，通常补充有用结构；C2 加入 C3，又可能把部分结构表达稀释。困难和边界自遮挡层中的差异较大。</p><div class="controls"><label>起点 → 联盟<select id="apair"></select></label><label>分层<select id="aaxis"></select></label><label>指标<select id="ametric"></select></label></div><div id="atable" class="tablewrap"></div><p class="muted">均值和中位数均来自同图差值。转折/遗漏分项有自己的有效支持；表中“正/负”表示数值方向。完整联盟改变实际人数。可评率变化单列，缺失 Q 不记 0。</p><p class="sources"><a href="../mixtures/DSTRUCT_ALLIANCE_STRATA.csv">完整分层表</a> · <a href="../mixtures/DSTRUCT_ALLIANCE_SUPPORT.csv">支持变化</a> · <a href="../mixtures/DSTRUCT_DIFFICULTY_STRUCTURE_CROSS.csv">难度×结构交叉</a> · <a href="../mixtures/REPORT_ZH.html">混合专题</a></p></section>
<section id="fixed"><h2>2. 固定人数后，构成比例仍有方向</h2><p>DSTRUCT C2 少 1 人、C3 多 1 人：n=12 平均 +1.969 Q，n=20 平均 +1.192 Q。多数有限配比链逐步不下降，同时保留同配比成员波动。</p><div class="controls"><label>当前分类<select id="fmethod"></select></label><label>减少 → 增加<select id="fpair"></select></label><label>固定人数<select id="fn"></select></label><label>分层<select id="faxis"></select></label></div><div id="ftable" class="tablewrap"></div><p class="muted">相邻两配置的所有登记团队均有 Q；同图同候选池、固定背景。比较配置均值，不把每个均值差冒充一次实际成对换人。</p><p class="sources"><a href="../mixtures/FIXED_N_FOCUSED_STRATA.csv">完整固定人数统计</a> · <a href="../mixtures/SAME_CONFIGURATION_MEMBER_DISTRIBUTIONS.csv.gz">同配比成员分布</a> · <a href="../mixtures/FIXED_N_THREE_OR_MORE_LEVEL_CHAIN_STRATA.csv">连续配比链</a></p><details><summary>查看科研图和具体几何例</summary>__MIXTURE_FIGS__</details></section>
<section id="curve"><h2>3. 更早接近参考，与之后持续保持分别观察</h2><p>在同图已有随机路径中，前 6 人包含指定类别的一组通常具有早期质量优势。每组至少 16 条路径。默认查看固定完整路径的 Q 曲线；也可切换逐前缀有效 Q、低尾和首次/持续达标概率，进一步按难度查看。</p><div class="controls"><label>分类<select id="cmethod"></select></label><label>难度<select id="cdifficulty"></select></label><label>过程指标<select id="cmetric"></select></label></div><div id="cchart" class="chart"></div><div id="ctable" class="tablewrap"></div><p class="muted">线表示“早期有该类−没有该类”的图片等权差。完整路径 Q 固定同一批图片和6—20路径；逐前缀有效 Q 的路径可随 n 变。概率保留全部路径作分母。持续只指观察到的 n…20；全部 N 人的最终成员与 Q 相同。</p><figure><a href="../curves/FIG01_EARLY_QUALITY_AND_NAMED_MIXTURES.png"><img src="../curves/FIG01_EARLY_QUALITY_AND_NAMED_MIXTURES.png" alt="固定完整路径的质量差及具名混合类别" loading="lazy"></a><figcaption>科研图的 Q 曲线使用完整 6—20 人路径，路径与图片队列固定；其均值口径与上方逐前缀可评表分别保留。</figcaption></figure><figure><a href="../curves/FIG02_FIRST_VS_SUSTAINED_TARGET_CROSSING.png"><img src="../curves/FIG02_FIRST_VS_SUSTAINED_TARGET_CROSSING.png" alt="困难图片首次与持续达标差异" loading="lazy"></a></figure><p class="sources"><a href="../curves/REPORT_ZH.html">进入过程专题</a> · <a href="../curves/NAMED_MIXTURE_SUMMARY.csv">具名组合统计</a> · <a href="../curves/LANDMARK_RECORDED_LABOR_SUMMARY.csv">同源劳动预算</a></p></section>
<section id="abc"><h2>4. C1↔C3 50% 严格 ABC：真实新端点</h2><p>8/4 回答各方向可实现的最大容量条件；6/3 用同图、同 D 和同一四端点直接比较两方向。GS 衡量跨类额外变化，Q 位移衡量实际升降。</p><div class="controls"><label>实验<select id="bstudy"></select></label><label>方向<select id="bdirection"></select></label><label>共同支持<select id="bsupport"></select></label><label>指标<select id="bmetric"></select></label><label>分层<select id="baxis"></select></label></div><div id="btable" class="tablewrap"></div><figure><a href="../c13_half/figures/C13_STRICT_50PCT_GS.png"><img src="../c13_half/figures/C13_STRICT_50PCT_GS.png" alt="C1↔C3严格半队替换的逐图幅度" loading="lazy"></a></figure><p class="muted">3,200 事件、4,992 唯一团队，48 张不同图片。4,898 端有 Q，94 端无连接；自动新端点不借用其他团队人工环序。正式可评、相机可见核诊断和核内敏感性在专题内分列。</p><p class="sources"><a href="../c13_half/REPORT_ZH.html">严格 ABC 完整报告</a> · <a href="../c13_half/analysis/SUPPORT.csv">支持与缺失</a> · <a href="../c13_half/analysis/PAIRED_FOUR_SUMMARY.csv">共享四端点结果</a> · <a href="../c13_half/design/DESIGN.json">冻结设计</a></p></section>
<section><h2>5. 实际补接与采用结论</h2><p>K4 小池的 1,081 个端点命中两个已批准人工顺序，辅助统计已接入，自动版保留。优先高历史 Q 的早期均差由 +1.500 更新为 +1.534；主目标自然路径未命中人工端点。</p><div id="ledger" class="tablewrap"></div><p><a href="../CONCLUSION_LEDGER.csv">全部逐条结论及来源</a> · <a href="../METHODS_AND_SCOPE.html">方法与范围</a> · <a href="../SOURCE_AND_REPRODUCTION.html">来源与复现</a> · <a href="../../../data/releases/v2.1/CURRENT_RESEARCH_BASIS.md">v2.1 当前采用口径</a></p></section>
<footer>所有数据内嵌，页面无需网络。静态表、逐队结果和代码随批次交付。Q=B8L2，参考与有效预处理保持；新分类选型和大规模进入策略未扩展。</footer></main><script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);
const names={TARGET_DSTRUCT_K3:'DSTRUCT K3',RFUSE_GEOM_K2:'RFUSE GEOM K2',OPPJOINT_K3:'JOINT K3',OPPJOINT_K4:'JOINT K4',ALL:'全部',all:'全部',official_difficulty:'官方难度',difficulty:'官方难度',purpose:'房间用途',room_type:'房间用途',structural_condition:'结构条件',main_8_4:'8 人换 4 人',paired_6_3:'6 人换 3 人·同图同 D',C1_to_C3:'C1 → C3',C3_to_C1:'C3 → C1',ABC_valid:'每事件三端 Q',all_four_valid:'同一四端共同 Q',B8L2:'Q / B8L2',D10:'D10',IoU3D100:'3D IoU×100',fusion_turn_n:'转折数',fusion_short_turn_edges:'短转折边数',boundary_loss:'边界损失',direction_loss:'方向损失',height_loss:'高度损失',omission:'参考遗漏',extension:'参考外延',Q_availability_change:'可评率变化',Q_complete:'完整6—20路径 Q',D10_complete:'完整6—20路径 D10',Q:'逐前缀可评 Q',Q_p10:'逐前缀 Q 第10百分位',ever_Q80:'曾 Q≥80 的概率',sustained_Q80_through20:'从当前人数到20持续 Q≥80',ever_Q90:'曾 Q≥90 的概率',score_available:'Q 可评率',Q_GS:'GS：对称跨类额外幅度',Q_GA:'GA：同起点跨类额外幅度',Q_class_shift:'Q_C−(Q_A+Q_B)/2',Q_CA:'Q_C−Q_A',Q_CB:'Q_C−Q_B',Q_W:'同类变化幅度 W',Q_cross:'跨类对称幅度'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=s=>names[s]||String(s).replaceAll('|','+');
const fmt=(x,n=3)=>x===null||x===undefined||!Number.isFinite(Number(x))?'—':Number(x).toFixed(n);
const uniq=a=>[...new Set(a)].sort((a,b)=>typeof a==='number'?a-b:String(a).localeCompare(String(b),'zh'));
function options(id,values,wanted){const previous=$(id).value;$(id).innerHTML=uniq(values).map(v=>`<option value="${esc(v)}">${esc(label(v))}</option>`).join('');if(values.includes(wanted))$(id).value=wanted;else if(values.includes(previous))$(id).value=previous;}
function table(id,heads,rows){$(id).innerHTML=rows.length?`<table><thead><tr>${heads.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`:'<p>此条件无对应共同支持；完整登记与缺失见源表。</p>';}
function standard(r){return [label(r.stratum),fmt(r.image_mean),fmt(r.image_median),r.valid_images+' / '+r.buildings,r.positive_images+' / '+r.negative_images+' / '+r.zero_images,fmt(r.building_mean)];}
options('apair',D.alliance.map(r=>r.from_classes+' → '+r.to_classes),'C2 → C2|C3');options('aaxis',['ALL','official_difficulty','structural_condition','purpose'],'official_difficulty');options('ametric',D.alliance.map(r=>r.metric),'B8L2');
function alliance(){const rr=D.alliance.filter(r=>r.from_classes+' → '+r.to_classes===$('apair').value&&r.axis===$('aaxis').value&&r.metric===$('ametric').value);table('atable',['条件','图等权差','中位数','图 / 楼','正 / 负 / 平','楼等权差'],rr.map(standard));}
['apair','aaxis','ametric'].forEach(id=>$(id).addEventListener('change',alliance));alliance();
options('fmethod',D.fixed.map(r=>r.method),'TARGET_DSTRUCT_K3');options('faxis',['ALL','official_difficulty','structural_condition','purpose'],'ALL');
function fixed(reset=true){let r=D.fixed.filter(r=>r.method===$('fmethod').value);if(reset){options('fpair',r.map(x=>x.from_class+' → '+x.to_class),'C2 → C3');options('fn',r.map(x=>x.n),12);}r=r.filter(r=>r.from_class+' → '+r.to_class===$('fpair').value&&String(r.n)===$('fn').value&&r.axis===$('faxis').value);table('ftable',['条件','平均 ΔQ','中位数','图 / 楼','正 / 负 / 平','楼等权差'],r.map(standard));}
$('fmethod').addEventListener('change',()=>fixed(true));['fpair','fn','faxis'].forEach(id=>$(id).addEventListener('change',()=>fixed(false)));fixed(true);
options('cmethod',D.curve.map(r=>r.method),'TARGET_DSTRUCT_K3');options('cdifficulty',['ALL','简单','中等','困难'],'ALL');options('cmetric',['Q_complete','Q','Q_p10','ever_Q80','sustained_Q80_through20','ever_Q90'],'Q_complete');
function plot(rr){if(!rr.length){$('cchart').innerHTML='';return;}const pct=$('cmetric').value.includes('ever_')||$('cmetric').value.includes('sustained_');const factor=pct?100:1;let vs=rr.map(r=>r.mean_image*factor),lo=Math.min(0,...vs),hi=Math.max(0,...vs);if(hi===lo)hi=lo+1;const pad=(hi-lo)*.12;lo-=pad;hi+=pad;const W=1000,H=310,L=70,R=25,T=20,B=45;const X=k=>L+(k-6)/14*(W-L-R),Y=v=>T+(hi-v)/(hi-lo)*(H-T-B);let svg=`<svg role="img" aria-label="所选条件的质量或达标概率差曲线" viewBox="0 0 ${W} ${H}">`;for(let i=0;i<5;i++){const y=lo+(hi-lo)*i/4;svg+=`<line x1="${L}" y1="${Y(y)}" x2="${W-R}" y2="${Y(y)}" stroke="#dce5e9"/><text x="${L-10}" y="${Y(y)+5}" text-anchor="end" fill="#556b78" font-size="13">${y.toFixed(1)}</text>`;}svg+=`<line x1="${L}" y1="${Y(0)}" x2="${W-R}" y2="${Y(0)}" stroke="#879ca8"/>`;[6,8,10,12,14,16,18,20].forEach(k=>svg+=`<text x="${X(k)}" y="${H-17}" text-anchor="middle" fill="#556b78" font-size="14">${k}</text>`);svg+=`<polyline fill="none" stroke="#136e7d" stroke-width="3" points="${rr.map(r=>X(r.k)+','+Y(r.mean_image*factor)).join(' ')}"/>`;rr.forEach(r=>svg+=`<circle cx="${X(r.k)}" cy="${Y(r.mean_image*factor)}" r="4" fill="#136e7d"><title>n=${r.k}；差=${fmt(r.mean_image*factor)}${pct?'个百分点':'Q'}；${r.images}图/${r.buildings}楼</title></circle>`);$('cchart').innerHTML=svg+'</svg>';}
function curves(){options('cdifficulty',$('cmetric').value.endsWith('_complete')?['ALL']:['ALL','简单','中等','困难']);const rr=D.curve.filter(r=>r.method===$('cmethod').value&&r.difficulty===$('cdifficulty').value&&r.metric===$('cmetric').value).sort((a,b)=>a.k-b.k);const pct=$('cmetric').value.includes('ever_')||$('cmetric').value.includes('sustained_'),f=pct?100:1;plot(rr);table('ctable',['人数',pct?'差（百分点）':'Q 差','图 / 楼','正 / 负 / 平','楼等权差'],rr.map(r=>[r.k,fmt(r.mean_image*f),r.images+' / '+r.buildings,r.positive_images+' / '+r.negative_images+' / '+r.tie_images,fmt(r.mean_building*f)]));}
['cmethod','cdifficulty','cmetric'].forEach(id=>$(id).addEventListener('change',curves));curves();
options('bstudy',['main_8_4','paired_6_3'],'paired_6_3');options('bdirection',['C1_to_C3','C3_to_C1'],'C1_to_C3');options('bmetric',D.abc.map(r=>r.metric),'Q_GS');options('baxis',['all','difficulty','room_type'],'all');
function abc(reset=false){let r=D.abc.filter(r=>r.study===$('bstudy').value&&r.direction===$('bdirection').value);if(reset)options('bsupport',r.map(x=>x.support),$('bstudy').value==='paired_6_3'?'all_four_valid':'ABC_valid');r=r.filter(r=>r.support===$('bsupport').value&&r.metric===$('bmetric').value&&r.stratum_type===$('baxis').value);table('btable',['条件','图等权差','中位数','图 / 楼','正 / 负 / 平','建筑聚类95%区间','楼等权差'],r.map(r=>[label(r.stratum),fmt(r.image_equal_mean),fmt(r.image_median),r.images+' / '+r.buildings,r.positive_images+' / '+r.negative_images+' / '+r.zero_images,'['+fmt(r.cluster_bootstrap_low)+', '+fmt(r.cluster_bootstrap_high)+']',fmt(r.building_equal_mean)]));}
['bstudy','bdirection'].forEach(id=>$(id).addEventListener('change',()=>abc(true)));['bsupport','bmetric','baxis'].forEach(id=>$(id).addEventListener('change',()=>abc(false)));abc(true);
table('ledger',['问题','采用判断','结论'],D.ledger.map(r=>[r.question,r.adoption,r.conclusion]));
</script></body></html>'''
html=html.replace('__DATA__',json.dumps(DATA,ensure_ascii=False,separators=(',',':'),allow_nan=False).replace('</','<\\/')).replace('__MIXTURE_FIGS__',figs)
(OUT/'index.html').write_text(html,encoding='utf-8')
print(json.dumps({'path':str(OUT/'index.html'),'bytes':len(html.encode()),'rows':{k:len(v) for k,v in DATA.items()}},ensure_ascii=False))
